{
  "name": "opencode-go-quota-sidebar",
  "version": "0.1.0",
  "type": "module",
  "description": "OpenCode Go quota in the OpenCode sidebar",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/silvaire-qwq/opencode-go-quota-sidebar.git"
  },
  "homepage": "https://github.com/silvaire-qwq/opencode-go-quota-sidebar#readme",
  "bugs": {
    "url": "https://github.com/silvaire-qwq/opencode-go-quota-sidebar/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-go",
    "tui",
    "sidebar",
    "quota"
  ],
  "exports": {
    "./tui": "./dist/tui.js",
    "./package.json": "./package.json"
  },
  "files": [
    "dist",
    "src"
  ],
  "scripts": {
    "build": "node scripts/build.mjs",
    "typecheck": "tsc --noEmit"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.2.0",
    "@opentui/core": ">=0.8.0",
    "@opentui/solid": ">=0.8.0",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": { "optional": true },
    "@opentui/core": { "optional": true },
    "@opentui/solid": { "optional": true },
    "solid-js": { "optional": true }
  },
  "devDependencies": {
    "@babel/core": "^7.28.0",
    "@babel/preset-typescript": "^7.27.1",
    "@opencode/plugin": "2.2.5",
    "@opentui/core": "0.8.0",
    "@opentui/solid": "0.8.0",
    "@types/node": "^26.6.6",
    "babel-preset-solid": "^1.9.16",
    "solid-js": "1.9.16",
    "typescript": "^5.9.3"
  }
}
